import arrow

arw = arrow.utcnow()

locales = ["fi", "fi-fi", "ne", "ne-np", "ee", "et", "zu", "zu-za"]

for locale in locales:
    try:
        arw.dehumanize("1 second ago", locale=locale)
        print(f"Locale {locale} is supported")
    except ValueError as e:
        print(f"Locale {locale} is NOT supported: {e}")

